#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench ot_hbm_su_programme_pslice_c5_flat (flat) vs ot_hbm_su_programme_pslice_c5_lp + mutants [1, 2] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash rtl/hbm_accel/generic/adapters/static_su/programme/landed/ot_hbm_su_programme_pslice_c5_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator; ONLY="1" runs just those mutants)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/hbm_accel/generic/adapters/static_su/programme/ot_hbm_su_programme_pslice_c5_flat.sv rtl/lib/ot_rst_relay.sv rtl/hbm_accel/generic/adapters/static_su/programme/ot_hbm_su_programme.sv rtl/hbm_accel/generic/adapters/static_su/programme/ot_hbm_su_programme_part.sv rtl/hbm_accel/generic/adapters/static_su/programme/ot_hbm_su_programme_pgcol.sv physical/asap7_memory_macros/ot_sram_1r1w_128x256_m1_r2c2/ot_sram_1r1w_128x256_m1_r2c2.v rtl/common/landed_parent/ot_pl_land.sv rtl/hbm_accel/generic/adapters/static_su/programme/landed/ot_hbm_su_programme_pslice_c5_flat_lagref.sv rtl/hbm_accel/generic/adapters/static_su/programme/landed/ot_hbm_su_programme_pslice_c5_lp.sv rtl/hbm_accel/generic/adapters/static_su/programme/landed/tb_ot_hbm_su_programme_pslice_c5_lp.sv"
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/pslice_c5.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/pslice_c5.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in ${ONLY:-0 1 2}; do
  if [ "$SIM" = verilator ]; then
    verilator --binary -j 8 -Wno-fatal --top-module tb_ot_hbm_su_programme_pslice_c5_lp -GMUT=$m  $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_ot_hbm_su_programme_pslice_c5_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -o "$OUT/sim$m" -s tb_ot_hbm_su_programme_pslice_c5_lp -Ptb_ot_hbm_su_programme_pslice_c5_lp.MUT=$m  $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
